recipes.code:
{
  "inputs": [
    {
      "id": "sonenta-api-key",
      "type": "promptString",
      "description": "Sonenta API key (mcp:* scope). If omitted, the server reads it from ~/.sonenta/credentials (run `sonenta login`). Legacy SONENTA_TOKEN / VERBUMIA_API_KEY / VERBUMIA_TOKEN are also accepted.",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@sonenta/mcp@0.46.2"
      ],
      "env": {
        "SONENTA_API_KEY": "${input:sonenta-api-key}",
        "SONENTA_API_BASE": "https://api.sonenta.dev",
        "SONENTA_PROJECTS": "<sonenta-projects>",
        "SONENTA_AGENT_NAME": "<sonenta-agent-name>",
        "SONENTA_AGENT_TYPE": "<sonenta-agent-type>",
        "SONENTA_AGENT_VERSION": "<sonenta-agent-version>"
      }
    }
  }
}
